  for($completed=1;$completed -le $steps;$completed++){$t+=$dt;if($t -ge $next -or $completed -eq $steps){[void]$rows.Add([ordered]@{part=$rows.Count;completed_steps=$completed;saved_step=$completed-1;time_s=[double]$t});$next=NextTime $t $state $segments}}
  $wanted=@($expected);Need ($rows.Count -eq 1746 -and $wanted.Count -eq 1746 -and $t -eq $end -and $end -eq (Number '9.152950286865234375')) 'Mid schedule/end differs'
  for($i=0;$i -lt $rows.Count;$i++){Need ($rows[$i].completed_steps -eq $wanted[$i] -and $rows[$i].saved_step -eq $(if($i){$wanted[$i]-1}else{0}) -and [BitConverter]::DoubleToInt64Bits($rows[$i].time_s) -eq [BitConverter]::DoubleToInt64Bits([double]$wanted[$i]*$dt)) 'Literal replay and integer union differ'}
